import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.C5oN-8Wt.js";const p=JSON.parse('{"title":"GNSS 录制信号源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.5.0-beta/modules/gnss_recording_source/index.md","filePath":"v0.5.0-beta/modules/gnss_recording_source/index.md"}'),o={name:"v0.5.0-beta/modules/gnss_recording_source/index.md"};function n(s,t,h,i,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="gnss-录制信号源" tabindex="-1">GNSS 录制信号源 <a class="header-anchor" href="#gnss-录制信号源" aria-label="Permalink to &quot;GNSS 录制信号源&quot;">​</a></h1><h2 id="它做什么" tabindex="-1">它做什么 <a class="header-anchor" href="#它做什么" aria-label="Permalink to &quot;它做什么&quot;">​</a></h2><p>GNSS 录制信号源将本次要读取的 I/Q 文件交给接收机。I 和 Q 是同一时刻录下的一对数值，接收机通过这些数值寻找 GPS 信号。</p><h2 id="接线" tabindex="-1">接线 <a class="header-anchor" href="#接线" aria-label="Permalink to &quot;接线&quot;">​</a></h2><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>recording</code>（录制文件）</td><td><code>gnss_recording</code></td><td>文件引用</td></tr></tbody></table><p>把“录制文件”输出接到 <a href="./../gnss_receiver/">GNSS 接收机</a>的“录制文件”输入。连接中传递的是文件引用。查看位置时，在观察器中选择接收机输出。</p><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>原始 IQ 样本<br><code>sample_path</code></td><td>内置定位样本</td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr></tbody></table><p>“原始 IQ 样本”选择 <strong>内置定位样本</strong>时，Master 使用安装实验环境时准备好的录制信号。</p><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p><a href="./../../learn/recorded-gnss/">录制信号定位</a>从这一路样本开始。第一次打开本课时，按<a href="./../../setup/linux-environment/">安装导航实验环境</a>准备默认录制文件。</p>',14)])])}const b=e(o,[["render",n]]);export{p as __pageData,b as default};
